__hydrateVak("vmbo","ak",{"A":{"sv":[{"v":"Wat is het verschil tussen weer en klimaat?","o":["Ze zijn hetzelfde","Weer is nu, klimaat is gemiddeld over 30 jaar","Weer is gemiddeld","Klimaat is van vandaag"],"c":1,"d":2,"u":"Weer is nu, klimaat over lange tijd.","uo":["Nee, het juiste antwoord is «Weer is nu, klimaat is gemiddeld over 30 jaar».","Klopt: weer is nu, klimaat over lange tijd.","Nee, dat is klimaat.","Nee, het juiste antwoord is «Weer is nu, klimaat is gemiddeld over 30 jaar»."],"uh":"Weer is nu, klimaat over lange tijd."},{"v":"Wat gebeurt er in een lagedrukgebied?","o":["Droog en zonnig","De lucht daalt","Vaak bewolkt en nat","Geen wind"],"c":2,"d":2,"u":"Opstijgende lucht, vaak nat.","uo":["Dat is hogedruk.","De lucht stijgt juist.","Klopt: opstijgende lucht, vaak nat.","Er is juist wind."],"uh":"Vaak bewolkt en nat: Opstijgende lucht, vaak nat."},{"v":"Wat is wind?","o":["Bewegende lucht van hoge naar lage druk","Stilstaande lucht","Warme grond","Regen"],"c":0,"d":1,"u":"Lucht stroomt van hoge naar lage druk.","uo":["Klopt: lucht stroomt van hoge naar lage druk.","Nee, het juiste antwoord is «Bewegende lucht van hoge naar lage druk».","Nee, het juiste antwoord is «Bewegende lucht van hoge naar lage druk».","Nee, het juiste antwoord is «Bewegende lucht van hoge naar lage druk»."],"uh":"Bewegende lucht van hoge naar lage druk: Lucht stroomt van hoge naar lage druk."},{"v":"Wat lees je af aan een klimaatgrafiek?","o":["Alleen de wind","De hoogte","De bevolking","Temperatuur en neerslag per maand"],"c":3,"d":2,"u":"Gemiddelde temperatuur en neerslag per maand.","uo":["Nee, het juiste antwoord is «Temperatuur en neerslag per maand».","Nee, het juiste antwoord is «Temperatuur en neerslag per maand».","Nee, het juiste antwoord is «Temperatuur en neerslag per maand».","Klopt: gemiddelde temperatuur en neerslag per maand."],"uh":"Temperatuur en neerslag per maand: Gemiddelde temperatuur en neerslag per maand."},{"v":"Nederland heeft een...","o":["woestijnklimaat","zeeklimaat","poolklimaat","landklimaat"],"c":1,"d":2,"u":"Mild door de zee.","uo":["Nee, het juiste antwoord is «zeeklimaat».","Klopt: mild door de zee.","Nee, het juiste antwoord is «zeeklimaat».","Dat is ver van zee."],"uh":"zeeklimaat: Mild door de zee."},{"v":"Wat is een hogedrukgebied?","o":["Nat en bewolkt","Veel wind","Vaak droog en zonnig","Vol neerslag"],"c":2,"d":2,"u":"Dalende lucht, droog weer.","uo":["Dat is lagedruk.","Nee, het juiste antwoord is «Vaak droog en zonnig».","Klopt: dalende lucht, droog weer.","Nee, het juiste antwoord is «Vaak droog en zonnig»."],"uh":"Vaak droog en zonnig: Dalende lucht, droog weer."},{"v":"Wat is neerslag?","o":["Regen en sneeuw","Wind","Temperatuur","Luchtdruk"],"c":0,"d":1,"u":"Water dat uit de lucht valt.","uo":["Klopt: water dat uit de lucht valt.","Nee, het juiste antwoord is «Regen en sneeuw».","Nee, het juiste antwoord is «Regen en sneeuw».","Nee, het juiste antwoord is «Regen en sneeuw»."],"uh":"Regen en sneeuw: Water dat uit de lucht valt."},{"v":"Wat is een isobar op een weerkaart?","o":["Een grens tussen landen","Een rivier","Een weg","Een lijn van gelijke luchtdruk"],"c":3,"d":3,"u":"Verbindt punten met dezelfde luchtdruk.","uo":["Nee, het juiste antwoord is «Een lijn van gelijke luchtdruk».","Nee, het juiste antwoord is «Een lijn van gelijke luchtdruk».","Nee, het juiste antwoord is «Een lijn van gelijke luchtdruk».","Klopt: verbindt punten met dezelfde luchtdruk."],"uh":"Een lijn van gelijke luchtdruk: Verbindt punten met dezelfde luchtdruk."},{"v":"Wat is een landklimaat?","o":["Mild door de zee","Koude winters en warme zomers","Altijd warm","Altijd nat"],"c":1,"d":2,"u":"Extreem, ver van zee.","uo":["Dat is zeeklimaat.","Klopt: extreem, ver van zee.","Nee, het juiste antwoord is «Koude winters en warme zomers».","Nee, het juiste antwoord is «Koude winters en warme zomers»."],"uh":"Koude winters en warme zomers: Extreem, ver van zee."},{"v":"Wat is een front?","o":["Een hogedrukgebied","Een isobar","De grens tussen warme en koude lucht","Een klimaatgrafiek"],"c":2,"d":2,"u":"De grens tussen warme en koude lucht.","uo":["Nee, het juiste antwoord is «De grens tussen warme en koude lucht».","Nee, het juiste antwoord is «De grens tussen warme en koude lucht».","Klopt: de grens tussen warme en koude lucht.","Nee, het juiste antwoord is «De grens tussen warme en koude lucht»."],"uh":"De grens tussen warme en koude lucht."},{"v":"Waarom is het bij een zeeklimaat mild?","o":["Door de invloed van de zee","Door de woestijn","Door bergen","Door de stad"],"c":0,"d":3,"u":"De zee zorgt voor milde temperaturen.","uo":["Klopt: de zee zorgt voor milde temperaturen.","Nee, het juiste antwoord is «Door de invloed van de zee».","Nee, het juiste antwoord is «Door de invloed van de zee».","Nee, het juiste antwoord is «Door de invloed van de zee»."],"uh":"Door de invloed van de zee: De zee zorgt voor milde temperaturen."}],"begrippen":[{"t":"Weer","d":"de toestand van de atmosfeer op een bepaald moment"},{"t":"Klimaat","d":"het gemiddelde weer over een lange periode van dertig jaar"},{"t":"Luchtdruk","d":"de druk die de lucht op het aardoppervlak uitoefent"},{"t":"Lagedrukgebied","d":"een gebied met lage luchtdruk, vaak bewolkt en nat"},{"t":"Hogedrukgebied","d":"een gebied met hoge luchtdruk, vaak droog en zonnig"},{"t":"Wind","d":"bewegende lucht van een hogedruk- naar een lagedrukgebied"},{"t":"Wet van Buys Ballot","d":"de regel die de windrichting rond hoge- en lagedrukgebieden beschrijft"},{"t":"Neerslag","d":"water dat uit de lucht valt, zoals regen en sneeuw"},{"t":"Temperatuur","d":"de mate van warmte, gemeten in graden"},{"t":"Klimaatgrafiek","d":"een grafiek met de gemiddelde temperatuur en neerslag per maand"},{"t":"Isobar","d":"een lijn op een weerkaart die punten met gelijke luchtdruk verbindt"},{"t":"Front","d":"de grens tussen warme en koude lucht"},{"t":"Zeeklimaat","d":"een klimaat met milde winters en koele zomers door de zee"},{"t":"Landklimaat","d":"een klimaat met koude winters en warme zomers, ver van zee"}],"sam":"<div class=\"sam-intro\"><strong>Weer</strong> is de toestand van de atmosfeer op een moment; <strong>klimaat</strong> is het gemiddelde weer over dertig jaar. Lucht stroomt van een <strong>hogedrukgebied</strong> naar een <strong>lagedrukgebied</strong>: dat is <strong>wind</strong>.</div><div class=\"sam-head\">1. Weer en klimaat</div><p><strong>Weer</strong> beschrijft de toestand van de lucht op één moment (nu regen, straks zon). <strong>Klimaat</strong> is het gemiddelde weer over een lange periode, meestal dertig jaar. Nederland heeft een <strong>zeeklimaat</strong>: milde winters en koele zomers door de invloed van de zee. Ver van zee heerst een <strong>landklimaat</strong> met koude winters en warme zomers.</p><div class=\"sam-head\">2. Luchtdruk en wind</div><p>De <strong>luchtdruk</strong> is de druk die de lucht uitoefent. In een <strong>lagedrukgebied</strong> stijgt lucht op: vaak bewolkt en nat. In een <strong>hogedrukgebied</strong> daalt lucht: vaak droog en zonnig. Lucht stroomt van hoge naar lage druk, en die stroming is de <strong>wind</strong>. De <strong>wet van Buys Ballot</strong> beschrijft hoe de wind rond die gebieden draait.</p><p>Op een weerkaart verbindt een <strong>isobar</strong> punten met dezelfde luchtdruk, en een <strong>front</strong> is de grens tussen warme en koude lucht.</p><div class=\"sam-head\">3. Een klimaatgrafiek lezen</div><p>Een <strong>klimaatgrafiek</strong> laat per maand de gemiddelde <strong>temperatuur</strong> (als lijn) en de <strong>neerslag</strong> (als staven) zien. Zo herken je bijvoorbeeld een natte winter en een droge zomer, of andersom.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Weer</div><div class=\"sam-definitie-body\">de toestand van de atmosfeer op een bepaald moment.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Klimaat</div><div class=\"sam-definitie-body\">het gemiddelde weer over een lange periode van dertig jaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Luchtdruk</div><div class=\"sam-definitie-body\">de druk die de lucht op het aardoppervlak uitoefent.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lagedrukgebied</div><div class=\"sam-definitie-body\">een gebied met lage luchtdruk, vaak bewolkt en nat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Hogedrukgebied</div><div class=\"sam-definitie-body\">een gebied met hoge luchtdruk, vaak droog en zonnig.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wind</div><div class=\"sam-definitie-body\">bewegende lucht van een hogedruk- naar een lagedrukgebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wet van Buys Ballot</div><div class=\"sam-definitie-body\">de regel die de windrichting rond hoge- en lagedrukgebieden beschrijft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Neerslag</div><div class=\"sam-definitie-body\">water dat uit de lucht valt, zoals regen en sneeuw.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Temperatuur</div><div class=\"sam-definitie-body\">de mate van warmte, gemeten in graden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Klimaatgrafiek</div><div class=\"sam-definitie-body\">een grafiek met de gemiddelde temperatuur en neerslag per maand.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Isobar</div><div class=\"sam-definitie-body\">een lijn op een weerkaart die punten met gelijke luchtdruk verbindt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Front</div><div class=\"sam-definitie-body\">de grens tussen warme en koude lucht.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zeeklimaat</div><div class=\"sam-definitie-body\">een klimaat met milde winters en koele zomers door de zee.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Landklimaat</div><div class=\"sam-definitie-body\">een klimaat met koude winters en warme zomers, ver van zee.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Weer»</b> is toestand van de lucht nu, terwijl <b>«Klimaat»</b> gemiddeld weer, lange termijn is. <b>«Luchtdruk»</b> is druk van de lucht, terwijl <b>«Lagedrukgebied»</b> lage druk, nat weer is. <b>«Lagedrukgebied»</b> is lage druk, nat weer, terwijl <b>«Hogedrukgebied»</b> hoge druk, droog weer is. <b>«Wind»</b> is bewegende lucht, terwijl <b>«Luchtdruk»</b> druk van de lucht is.</div>"},"B":{"sv":[{"v":"Wat is de waterkringloop?","o":["Water dat verdwijnt","Verdamping, neerslag en afstroming","Alleen regen","Een rivier"],"c":1,"d":2,"u":"Water gaat rond via verdamping en neerslag.","uo":["Water verdwijnt niet.","Klopt: water gaat rond via verdamping en neerslag.","Nee, dat is één deel.","Nee, het juiste antwoord is «Verdamping, neerslag en afstroming»."],"uh":"Verdamping, neerslag en afstroming: Water gaat rond via verdamping en neerslag."},{"v":"Wat is verdamping?","o":["Regen die valt","Water dat bevriest","Water dat waterdamp wordt","Water in de bodem"],"c":2,"d":1,"u":"Water wordt waterdamp.","uo":["Dat is neerslag.","Nee, het juiste antwoord is «Water dat waterdamp wordt».","Klopt: water wordt waterdamp.","Dat is grondwater."],"uh":"Water dat waterdamp wordt: Water wordt waterdamp."},{"v":"Wat doet een dijk?","o":["Houdt het water tegen","Pompt water weg","Maakt regen","Legt land droog"],"c":0,"d":1,"u":"Een dijk houdt het water tegen.","uo":["Klopt: een dijk houdt het water tegen.","Dat doet een gemaal.","Nee, het juiste antwoord is «Houdt het water tegen».","Dat doet een polder."],"uh":"Houdt het water tegen: Een dijk houdt het water tegen."},{"v":"Wat is een polder?","o":["Een berg","Een woestijn","Een zee","Drooggelegd laaggelegen land"],"c":3,"d":2,"u":"Laag land dat door dijken en gemalen droog blijft.","uo":["Nee, het juiste antwoord is «Drooggelegd laaggelegen land».","Nee, het juiste antwoord is «Drooggelegd laaggelegen land».","Nee, het juiste antwoord is «Drooggelegd laaggelegen land».","Klopt: laag land dat door dijken en gemalen droog blijft."],"uh":"Drooggelegd laaggelegen land: Laag land dat door dijken en gemalen droog blijft."},{"v":"Wat doet een gemaal?","o":["Water tegenhouden","Overtollig water wegpompen","Regen maken","Dijken bouwen"],"c":1,"d":2,"u":"Het pompt overtollig water weg.","uo":["Dat doet een dijk.","Klopt: het pompt overtollig water weg.","Nee, het juiste antwoord is «Overtollig water wegpompen».","Nee, het juiste antwoord is «Overtollig water wegpompen»."],"uh":"Overtollig water wegpompen: Het pompt overtollig water weg."},{"v":"Wat is grondwater?","o":["Water in de zee","Regen in de lucht","Water in de bodem","Water in een rivier"],"c":2,"d":1,"u":"Water dat in de bodem zit.","uo":["Nee, het juiste antwoord is «Water in de bodem».","Nee, het juiste antwoord is «Water in de bodem».","Klopt: water dat in de bodem zit.","Nee, het juiste antwoord is «Water in de bodem»."],"uh":"Water in de bodem: Water dat in de bodem zit."},{"v":"Wat is een delta?","o":["Waar een rivier in zee uitmondt","Een berg","Een woestijn","Een dijk"],"c":0,"d":2,"u":"Waar een rivier zich vertakt en in zee uitmondt.","uo":["Klopt: waar een rivier zich vertakt en in zee uitmondt.","Nee, het juiste antwoord is «Waar een rivier in zee uitmondt».","Nee, het juiste antwoord is «Waar een rivier in zee uitmondt».","Nee, het juiste antwoord is «Waar een rivier in zee uitmondt»."],"uh":"Waar een rivier zich vertakt en in zee uitmondt."},{"v":"Waardoor neemt het overstromingsrisico toe?","o":["Door minder regen","Door een lagere zeespiegel","Door meer dijken","Door zeespiegelstijging"],"c":3,"d":3,"u":"Door de stijgende zeespiegel.","uo":["Nee, het juiste antwoord is «Door zeespiegelstijging».","Juist andersom.","Dijken helpen juist.","Klopt: door de stijgende zeespiegel."],"uh":"Door zeespiegelstijging: Door de stijgende zeespiegel."},{"v":"Wat beheert het waterschap?","o":["De wegen","De dijken en het waterpeil","De scholen","De belasting"],"c":1,"d":2,"u":"Het waterschap zorgt voor dijken en waterpeil.","uo":["Nee, het juiste antwoord is «De dijken en het waterpeil».","Klopt: het waterschap zorgt voor dijken en waterpeil.","Nee, het juiste antwoord is «De dijken en het waterpeil».","Nee, het juiste antwoord is «De dijken en het waterpeil»."],"uh":"De dijken en het waterpeil: Het waterschap zorgt voor dijken en waterpeil."},{"v":"Wat is een rivier?","o":["Stilstaand water","Water in de bodem","Stromend water naar de zee","Regen"],"c":2,"d":1,"u":"Stromend water dat naar zee gaat.","uo":["Nee, het juiste antwoord is «Stromend water naar de zee».","Dat is grondwater.","Klopt: stromend water dat naar zee gaat.","Nee, het juiste antwoord is «Stromend water naar de zee»."],"uh":"Stromend water dat naar zee gaat."},{"v":"Waarom is Nederland kwetsbaar voor water?","o":["Grote delen liggen laag","Het ligt hoog","Er is geen zee","Er valt nooit regen"],"c":0,"d":3,"u":"Veel land ligt onder zeeniveau.","uo":["Klopt: veel land ligt onder zeeniveau.","Juist niet, het juiste antwoord is «Grote delen liggen laag».","Er is wel zee.","Er valt wel regen."],"uh":"Grote delen liggen laag: Veel land ligt onder zeeniveau."}],"begrippen":[{"t":"Waterkringloop","d":"de kringloop van verdamping, neerslag en afstroming van water"},{"t":"Verdamping","d":"het overgaan van water in waterdamp"},{"t":"Neerslag","d":"water dat uit de lucht valt, zoals regen en sneeuw"},{"t":"Grondwater","d":"water dat zich in de bodem bevindt"},{"t":"Rivier","d":"stromend water dat richting de zee gaat"},{"t":"Delta","d":"het gebied waar een rivier zich vertakt en in zee uitmondt"},{"t":"Dijk","d":"een verhoging die het land tegen water beschermt"},{"t":"Polder","d":"laaggelegen land dat door dijken en gemalen droog blijft"},{"t":"Gemaal","d":"een installatie die overtollig water wegpompt"},{"t":"Overstroming","d":"het onderlopen van land met water"},{"t":"Zeespiegelstijging","d":"het stijgen van het gemiddelde zeeniveau"},{"t":"Waterschap","d":"het bestuur dat zorgt voor dijken en het waterpeil"}],"sam":"<div class=\"sam-intro\">In de <strong>waterkringloop</strong> verdampt water, valt het als <strong>neerslag</strong> en stroomt het via <strong>rivieren</strong> terug naar zee. Nederland ligt laag en beschermt zich met <strong>dijken</strong>, <strong>polders</strong> en <strong>gemalen</strong>.</div><div class=\"sam-head\">1. De waterkringloop</div><p>Water is voortdurend in beweging. Door <strong>verdamping</strong> wordt zeewater waterdamp, die als <strong>neerslag</strong> weer valt. Een deel zakt weg als <strong>grondwater</strong>, een deel stroomt via een <strong>rivier</strong> naar zee, waar de rivier zich in een <strong>delta</strong> vertakt. Dit geheel heet de <strong>waterkringloop</strong>.</p><div class=\"sam-head\">2. Nederland en het water</div><p>Grote delen van Nederland liggen onder zeeniveau. Een <strong>dijk</strong> houdt het water tegen, een <strong>polder</strong> is drooggelegd land en een <strong>gemaal</strong> pompt overtollig water weg. Het <strong>waterschap</strong> beheert de dijken en het waterpeil. Door <strong>zeespiegelstijging</strong> neemt het risico op <strong>overstroming</strong> toe.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Waterkringloop</div><div class=\"sam-definitie-body\">de kringloop van verdamping, neerslag en afstroming van water.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verdamping</div><div class=\"sam-definitie-body\">het overgaan van water in waterdamp.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Neerslag</div><div class=\"sam-definitie-body\">water dat uit de lucht valt, zoals regen en sneeuw.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondwater</div><div class=\"sam-definitie-body\">water dat zich in de bodem bevindt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rivier</div><div class=\"sam-definitie-body\">stromend water dat richting de zee gaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Delta</div><div class=\"sam-definitie-body\">het gebied waar een rivier zich vertakt en in zee uitmondt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Dijk</div><div class=\"sam-definitie-body\">een verhoging die het land tegen water beschermt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Polder</div><div class=\"sam-definitie-body\">laaggelegen land dat door dijken en gemalen droog blijft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gemaal</div><div class=\"sam-definitie-body\">een installatie die overtollig water wegpompt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Overstroming</div><div class=\"sam-definitie-body\">het onderlopen van land met water.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zeespiegelstijging</div><div class=\"sam-definitie-body\">het stijgen van het gemiddelde zeeniveau.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Waterschap</div><div class=\"sam-definitie-body\">het bestuur dat zorgt voor dijken en het waterpeil.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Waterkringloop»</b> is water gaat rond, terwijl <b>«Verdamping»</b> water wordt damp is. <b>«Verdamping»</b> is water wordt damp, terwijl <b>«Neerslag»</b> regen en sneeuw is. <b>«Grondwater»</b> is water in de bodem, terwijl <b>«Rivier»</b> stromend water naar zee is. <b>«Rivier»</b> is stromend water naar zee, terwijl <b>«Delta»</b> riviermonding in zee is.</div>"},"C":{"sv":[{"v":"Wat is het geboortecijfer?","o":["Aantal doden per 1000","Aantal geboorten per 1000 inwoners","De bevolkingsdichtheid","Het aantal migranten"],"c":1,"d":2,"u":"Geboorten per duizend inwoners.","uo":["Dat is het sterftecijfer.","Klopt: geboorten per duizend inwoners.","Nee, het juiste antwoord is «Aantal geboorten per 1000 inwoners».","Nee, het juiste antwoord is «Aantal geboorten per 1000 inwoners»."],"uh":"Aantal geboorten per 1000 inwoners: Geboorten per duizend inwoners."},{"v":"Wat is natuurlijke aanwas?","o":["Migratie","Bevolkingsdichtheid","Geboortecijfer min sterftecijfer","Verstedelijking"],"c":2,"d":3,"u":"Geboorten min sterfte.","uo":["Nee, het juiste antwoord is «Geboortecijfer min sterftecijfer».","Nee, het juiste antwoord is «Geboortecijfer min sterftecijfer».","Klopt: geboorten min sterfte.","Nee, het juiste antwoord is «Geboortecijfer min sterftecijfer»."],"uh":"Geboortecijfer min sterftecijfer: Geboorten min sterfte."},{"v":"Wat is immigratie?","o":["Een land binnenkomen","Een land verlaten","In de stad wonen","Op het platteland wonen"],"c":0,"d":1,"u":"Je vestigen in een nieuw land.","uo":["Klopt: je vestigen in een nieuw land.","Dat is emigratie.","Nee, het juiste antwoord is «Een land binnenkomen».","Nee, het juiste antwoord is «Een land binnenkomen»."],"uh":"Een land binnenkomen: Je vestigen in een nieuw land."},{"v":"Wat is emigratie?","o":["Een land binnenkomen","In de stad gaan wonen","Kinderen krijgen","Je eigen land verlaten"],"c":3,"d":2,"u":"Vertrekken uit je eigen land.","uo":["Dat is immigratie.","Nee, het juiste antwoord is «Je eigen land verlaten».","Nee, het juiste antwoord is «Je eigen land verlaten».","Klopt: vertrekken uit je eigen land."],"uh":"Je eigen land verlaten: Vertrekken uit je eigen land."},{"v":"Wat is verstedelijking?","o":["Steden krimpen","Steden groeien","Minder mensen","Meer platteland"],"c":1,"d":2,"u":"Steden groeien, meer stadsbewoners.","uo":["Juist niet, het juiste antwoord is «Steden groeien».","Klopt: steden groeien, meer stadsbewoners.","Nee, het juiste antwoord is «Steden groeien».","Nee, het juiste antwoord is «Steden groeien»."],"uh":"Steden groeien, meer stadsbewoners."},{"v":"Wat is bevolkingsdichtheid?","o":["Het aantal geboorten","Het aantal doden","Inwoners per vierkante kilometer","De migratie"],"c":2,"d":2,"u":"Inwoners per km².","uo":["Nee, het juiste antwoord is «Inwoners per vierkante kilometer».","Nee, het juiste antwoord is «Inwoners per vierkante kilometer».","Klopt: inwoners per km².","Nee, het juiste antwoord is «Inwoners per vierkante kilometer»."],"uh":"Inwoners per km²."},{"v":"Wat is vergrijzing?","o":["Meer ouderen in de bevolking","Meer kinderen","Meer migranten","Meer steden"],"c":0,"d":2,"u":"Het aandeel ouderen stijgt.","uo":["Klopt: het aandeel ouderen stijgt.","Nee, het juiste antwoord is «Meer ouderen in de bevolking».","Nee, het juiste antwoord is «Meer ouderen in de bevolking».","Nee, het juiste antwoord is «Meer ouderen in de bevolking»."],"uh":"Meer ouderen in de bevolking: Het aandeel ouderen stijgt."},{"v":"Wat is urbanisatie?","o":["Van stad naar platteland","Meer kinderen","Minder mensen","Van platteland naar de stad"],"c":3,"d":3,"u":"Mensen trekken van het platteland naar de stad.","uo":["Juist andersom.","Nee, het juiste antwoord is «Van platteland naar de stad».","Nee, het juiste antwoord is «Van platteland naar de stad».","Klopt: mensen trekken van het platteland naar de stad."],"uh":"Van platteland naar de stad: Mensen trekken van het platteland naar de stad."},{"v":"Wat is het sterftecijfer?","o":["Geboorten per 1000","Sterfgevallen per 1000 inwoners","De migratie","De dichtheid"],"c":1,"d":2,"u":"Sterfgevallen per duizend inwoners.","uo":["Dat is het geboortecijfer.","Klopt: sterfgevallen per duizend inwoners.","Nee, het juiste antwoord is «Sterfgevallen per 1000 inwoners».","Nee, het juiste antwoord is «Sterfgevallen per 1000 inwoners»."],"uh":"Sterfgevallen per duizend inwoners."},{"v":"Wat is migratie?","o":["Kinderen krijgen","In de stad wonen","Verhuizen naar een ander gebied","Sterven"],"c":2,"d":1,"u":"Mensen verhuizen naar een ander gebied.","uo":["Nee, het juiste antwoord is «Verhuizen naar een ander gebied».","Nee, het juiste antwoord is «Verhuizen naar een ander gebied».","Klopt: mensen verhuizen naar een ander gebied.","Nee, het juiste antwoord is «Verhuizen naar een ander gebied»."],"uh":"Verhuizen naar een ander gebied: Mensen verhuizen naar een ander gebied."},{"v":"Wat is het platteland?","o":["Dunbevolkt gebied buiten de stad","Het centrum van de stad","Een industriegebied","Een haven"],"c":0,"d":1,"u":"Dunbevolkt gebied buiten de stad.","uo":["Klopt: dunbevolkt gebied buiten de stad.","Nee, het juiste antwoord is «Dunbevolkt gebied buiten de stad».","Nee, het juiste antwoord is «Dunbevolkt gebied buiten de stad».","Nee, het juiste antwoord is «Dunbevolkt gebied buiten de stad»."],"uh":"Dunbevolkt gebied buiten de stad."}],"begrippen":[{"t":"Bevolkingsgroei","d":"de toename van het aantal inwoners van een gebied"},{"t":"Geboortecijfer","d":"het aantal geboorten per duizend inwoners per jaar"},{"t":"Sterftecijfer","d":"het aantal sterfgevallen per duizend inwoners per jaar"},{"t":"Natuurlijke aanwas","d":"het geboortecijfer min het sterftecijfer"},{"t":"Migratie","d":"het verhuizen van mensen naar een ander gebied"},{"t":"Immigratie","d":"het zich vestigen in een nieuw land"},{"t":"Emigratie","d":"het vertrekken uit je eigen land om elders te wonen"},{"t":"Verstedelijking","d":"de groei van steden en van het aandeel stadsbewoners"},{"t":"Bevolkingsdichtheid","d":"het aantal inwoners per vierkante kilometer"},{"t":"Vergrijzing","d":"de toename van het aandeel ouderen in de bevolking"},{"t":"Urbanisatie","d":"het trekken van mensen van het platteland naar de stad"},{"t":"Platteland","d":"dunbevolkt gebied buiten de stad"}],"sam":"<div class=\"sam-intro\">De <strong>bevolkingsgroei</strong> hangt af van het <strong>geboortecijfer</strong>, het <strong>sterftecijfer</strong> en <strong>migratie</strong>. Door <strong>verstedelijking</strong> trekken mensen naar de stad.</div><div class=\"sam-head\">1. Waardoor groeit een bevolking?</div><p>Een bevolking groeit door geboorte en immigratie, en krimpt door sterfte en emigratie. Het <strong>geboortecijfer</strong> en het <strong>sterftecijfer</strong> geven het aantal geboorten en sterfgevallen per duizend inwoners. Het verschil is de <strong>natuurlijke aanwas</strong>. Daarnaast telt <strong>migratie</strong> mee: <strong>immigratie</strong> is een land binnenkomen, <strong>emigratie</strong> is vertrekken.</p><div class=\"sam-head\">2. Steden en spreiding</div><p>Door <strong>verstedelijking</strong> groeien steden en neemt het aandeel stadsbewoners toe; het trekken van het platteland naar de stad heet <strong>urbanisatie</strong>. De <strong>bevolkingsdichtheid</strong> zegt hoeveel mensen er per vierkante kilometer wonen. In veel landen speelt ook <strong>vergrijzing</strong>: het aandeel ouderen stijgt.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bevolkingsgroei</div><div class=\"sam-definitie-body\">de toename van het aantal inwoners van een gebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geboortecijfer</div><div class=\"sam-definitie-body\">het aantal geboorten per duizend inwoners per jaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sterftecijfer</div><div class=\"sam-definitie-body\">het aantal sterfgevallen per duizend inwoners per jaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Natuurlijke aanwas</div><div class=\"sam-definitie-body\">het geboortecijfer min het sterftecijfer.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Migratie</div><div class=\"sam-definitie-body\">het verhuizen van mensen naar een ander gebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Immigratie</div><div class=\"sam-definitie-body\">het zich vestigen in een nieuw land.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Emigratie</div><div class=\"sam-definitie-body\">het vertrekken uit je eigen land om elders te wonen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verstedelijking</div><div class=\"sam-definitie-body\">de groei van steden en van het aandeel stadsbewoners.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bevolkingsdichtheid</div><div class=\"sam-definitie-body\">het aantal inwoners per vierkante kilometer.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vergrijzing</div><div class=\"sam-definitie-body\">de toename van het aandeel ouderen in de bevolking.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Urbanisatie</div><div class=\"sam-definitie-body\">het trekken van mensen van het platteland naar de stad.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Platteland</div><div class=\"sam-definitie-body\">dunbevolkt gebied buiten de stad.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Bevolkingsgroei»</b> is meer inwoners, terwijl <b>«Natuurlijke aanwas»</b> geboorten min sterfte is. <b>«Geboortecijfer»</b> is geboorten per 1000, terwijl <b>«Sterftecijfer»</b> sterfgevallen per 1000 is. <b>«Migratie»</b> is mensen verhuizen, terwijl <b>«Verstedelijking»</b> steden groeien is. <b>«Immigratie»</b> is een land binnenkomen, terwijl <b>«Emigratie»</b> je land verlaten is.</div>"},"D":{"sv":[{"v":"Wat is welvaart?","o":["Alleen geld","Hoe goed mensen in hun behoeften kunnen voorzien","Het weer","De bevolking"],"c":1,"d":2,"u":"Hoe goed men kan rondkomen.","uo":["Het is meer dan alleen geld.","Klopt: hoe goed men kan rondkomen.","Nee, het juiste antwoord is «Hoe goed mensen in hun behoeften kunnen voorzien».","Nee, het juiste antwoord is «Hoe goed mensen in hun behoeften kunnen voorzien»."],"uh":"Hoe goed men kan rondkomen."},{"v":"Wat meet het bnp per inwoner?","o":["De bevolking","Het weer","De gemiddelde productie per persoon","De oppervlakte"],"c":2,"d":3,"u":"De gemiddelde productie per persoon.","uo":["Nee, het juiste antwoord is «De gemiddelde productie per persoon».","Nee, het juiste antwoord is «De gemiddelde productie per persoon».","Klopt: de gemiddelde productie per persoon.","Nee, het juiste antwoord is «De gemiddelde productie per persoon»."],"uh":"De gemiddelde productie per persoon."},{"v":"Wat is een ontwikkelingsland?","o":["Een land met lage welvaart","Een rijk land","Een groot land","Een klein land"],"c":0,"d":1,"u":"Een land met lage welvaart.","uo":["Klopt: een land met lage welvaart.","Dat is een ontwikkeld land.","Nee, het juiste antwoord is «Een land met lage welvaart».","Nee, het juiste antwoord is «Een land met lage welvaart»."],"uh":"Een land met lage welvaart."},{"v":"Wat is een centrumgebied?","o":["Een arm randgebied","Een leeg gebied","Een woestijn","Een rijk gebied met veel bedrijvigheid"],"c":3,"d":2,"u":"Een rijk, welvarend kerngebied.","uo":["Dat is de periferie.","Nee, het juiste antwoord is «Een rijk gebied met veel bedrijvigheid».","Nee, het juiste antwoord is «Een rijk gebied met veel bedrijvigheid».","Klopt: een rijk, welvarend kerngebied."],"uh":"Een rijk gebied met veel bedrijvigheid: Een rijk, welvarend kerngebied."},{"v":"Wat is de periferie?","o":["Het rijke centrum","Een arm, afgelegen randgebied","De hoofdstad","Een fabriek"],"c":1,"d":2,"u":"Arm gebied aan de rand.","uo":["Juist het tegenovergestelde.","Klopt: arm gebied aan de rand.","Nee, het juiste antwoord is «Een arm, afgelegen randgebied».","Nee, het juiste antwoord is «Een arm, afgelegen randgebied»."],"uh":"Een arm, afgelegen randgebied: Arm gebied aan de rand."},{"v":"Wat is levensverwachting?","o":["Het geboortecijfer","De bevolking","Het gemiddelde aantal jaren dat iemand leeft","De welvaart"],"c":2,"d":2,"u":"De gemiddelde levensduur.","uo":["Nee, het juiste antwoord is «Het gemiddelde aantal jaren dat iemand leeft».","Nee, het juiste antwoord is «Het gemiddelde aantal jaren dat iemand leeft».","Klopt: de gemiddelde levensduur.","Nee, het juiste antwoord is «Het gemiddelde aantal jaren dat iemand leeft»."],"uh":"Het gemiddelde aantal jaren dat iemand leeft: De gemiddelde levensduur."},{"v":"Wat is analfabetisme?","o":["Niet kunnen lezen en schrijven","Rijk zijn","Ziek zijn","Werkloos zijn"],"c":0,"d":1,"u":"Niet kunnen lezen en schrijven.","uo":["Klopt: niet kunnen lezen en schrijven.","Nee, het juiste antwoord is «Niet kunnen lezen en schrijven».","Nee, het juiste antwoord is «Niet kunnen lezen en schrijven».","Nee, het juiste antwoord is «Niet kunnen lezen en schrijven»."],"uh":"Niet kunnen lezen en schrijven."},{"v":"Waardoor ontstaan welvaartsverschillen?","o":["Door het weer alleen","Door toeval","Door de kleur van de vlag","Door grondstoffen, onderwijs en handel"],"c":3,"d":3,"u":"Verschillen in grondstoffen, onderwijs en handel.","uo":["Niet alleen.","Nee, het juiste antwoord is «Door grondstoffen, onderwijs en handel».","Nee, het juiste antwoord is «Door grondstoffen, onderwijs en handel».","Klopt: verschillen in grondstoffen, onderwijs en handel."],"uh":"Door grondstoffen, onderwijs en handel: Verschillen in grondstoffen, onderwijs en handel."},{"v":"Wat is een ontwikkeld land?","o":["Een land met lage welvaart","Een land met hoge welvaart","Een klein land","Een warm land"],"c":1,"d":1,"u":"Een rijk land met hoge welvaart.","uo":["Dat is een ontwikkelingsland.","Klopt: een rijk land met hoge welvaart.","Nee, het juiste antwoord is «Een land met hoge welvaart».","Nee, het juiste antwoord is «Een land met hoge welvaart»."],"uh":"Een land met hoge welvaart: Een rijk land met hoge welvaart."},{"v":"Wat is ontwikkelingssamenwerking?","o":["Handel met winst","Belasting","Hulp aan armere landen","Een oorlog"],"c":2,"d":2,"u":"Hulp aan armere landen.","uo":["Nee, het juiste antwoord is «Hulp aan armere landen».","Nee, het juiste antwoord is «Hulp aan armere landen».","Klopt: hulp aan armere landen.","Nee, het juiste antwoord is «Hulp aan armere landen»."],"uh":"Hulp aan armere landen."},{"v":"Waarmee kan een land geld verdienen?","o":["Met grondstoffen","Met het weer","Met de vlag","Met de tijd"],"c":0,"d":2,"u":"Met grondstoffen kan een land geld verdienen.","uo":["Klopt: met grondstoffen kan een land geld verdienen.","Nee, het juiste antwoord is «Met grondstoffen».","Nee, het juiste antwoord is «Met grondstoffen».","Nee, het juiste antwoord is «Met grondstoffen»."],"uh":"Met grondstoffen kan een land geld verdienen."}],"begrippen":[{"t":"Welvaart","d":"de mate waarin mensen in hun behoeften kunnen voorzien"},{"t":"Bnp per inwoner","d":"de gemiddelde productie per persoon in een land"},{"t":"Ontwikkelingsland","d":"een land met een lage welvaart"},{"t":"Ontwikkeld land","d":"een land met een hoge welvaart"},{"t":"Centrum","d":"een rijk en welvarend gebied met veel bedrijvigheid"},{"t":"Periferie","d":"een arm en afgelegen gebied aan de rand"},{"t":"Welvaartsverschil","d":"het verschil in rijkdom tussen gebieden of landen"},{"t":"Analfabetisme","d":"het niet kunnen lezen en schrijven"},{"t":"Levensverwachting","d":"het gemiddelde aantal jaren dat iemand naar verwachting leeft"},{"t":"Grondstoffen","d":"natuurlijke stoffen waarmee een land geld kan verdienen"},{"t":"Infrastructuur","d":"voorzieningen zoals wegen, havens en spoor"},{"t":"Ontwikkelingssamenwerking","d":"hulp aan armere landen om zich te ontwikkelen"}],"sam":"<div class=\"sam-intro\">De <strong>welvaart</strong> verschilt sterk tussen landen; het <strong>bnp per inwoner</strong> is er een maat voor. Rijke <strong>centrumgebieden</strong> staan tegenover arme <strong>periferiegebieden</strong>.</div><div class=\"sam-head\">1. Welvaart meten</div><p><strong>Welvaart</strong> is de mate waarin mensen in hun behoeften kunnen voorzien. Je meet die onder meer met het <strong>bnp per inwoner</strong> (de gemiddelde productie per persoon), de <strong>levensverwachting</strong> en het <strong>analfabetisme</strong>. Landen met lage welvaart heten <strong>ontwikkelingslanden</strong>, landen met hoge welvaart <strong>ontwikkelde landen</strong>.</p><div class=\"sam-head\">2. Centrum en periferie</div><p>Binnen en tussen landen zie je een rijk <strong>centrum</strong> met veel bedrijvigheid en een arme <strong>periferie</strong> aan de rand. Zulke <strong>welvaartsverschillen</strong> ontstaan door verschillen in <strong>grondstoffen</strong>, onderwijs, <strong>infrastructuur</strong> en handel. Met <strong>ontwikkelingssamenwerking</strong> worden armere landen geholpen.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Welvaart</div><div class=\"sam-definitie-body\">de mate waarin mensen in hun behoeften kunnen voorzien.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bnp per inwoner</div><div class=\"sam-definitie-body\">de gemiddelde productie per persoon in een land.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontwikkelingsland</div><div class=\"sam-definitie-body\">een land met een lage welvaart.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontwikkeld land</div><div class=\"sam-definitie-body\">een land met een hoge welvaart.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Centrum</div><div class=\"sam-definitie-body\">een rijk en welvarend gebied met veel bedrijvigheid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Periferie</div><div class=\"sam-definitie-body\">een arm en afgelegen gebied aan de rand.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Welvaartsverschil</div><div class=\"sam-definitie-body\">het verschil in rijkdom tussen gebieden of landen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Analfabetisme</div><div class=\"sam-definitie-body\">het niet kunnen lezen en schrijven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Levensverwachting</div><div class=\"sam-definitie-body\">het gemiddelde aantal jaren dat iemand naar verwachting leeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondstoffen</div><div class=\"sam-definitie-body\">natuurlijke stoffen waarmee een land geld kan verdienen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Infrastructuur</div><div class=\"sam-definitie-body\">voorzieningen zoals wegen, havens en spoor.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ontwikkelingssamenwerking</div><div class=\"sam-definitie-body\">hulp aan armere landen om zich te ontwikkelen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Welvaart»</b> is hoe goed men rondkomt, terwijl <b>«Welvaartsverschil»</b> verschil in rijkdom is. <b>«Bnp per inwoner»</b> is productie per persoon, terwijl <b>«Levensverwachting»</b> gemiddelde levensduur is. <b>«Ontwikkelingsland»</b> is arm land, terwijl <b>«Ontwikkeld land»</b> rijk land is. <b>«Centrum»</b> is rijk kerngebied, terwijl <b>«Periferie»</b> arm randgebied is.</div>"},"E":{"sv":[{"v":"Wat is ruimtelijke ordening?","o":["De ruimte laten zoals hij is","Het plannen van het gebruik van de ruimte","Alleen bouwen","Alleen natuur"],"c":1,"d":2,"u":"Het indelen en plannen van de ruimte.","uo":["Nee, het juiste antwoord is «Het plannen van het gebruik van de ruimte».","Klopt: het indelen en plannen van de ruimte.","Nee, het juiste antwoord is «Het plannen van het gebruik van de ruimte».","Nee, het juiste antwoord is «Het plannen van het gebruik van de ruimte»."],"uh":"Het plannen van het gebruik van de ruimte: Het indelen en plannen van de ruimte."},{"v":"Wat legt een bestemmingsplan vast?","o":["De belasting","Het weer","Waarvoor grond gebruikt mag worden","De bevolking"],"c":2,"d":2,"u":"Waarvoor grond gebruikt mag worden.","uo":["Nee, het juiste antwoord is «Waarvoor grond gebruikt mag worden».","Nee, het juiste antwoord is «Waarvoor grond gebruikt mag worden».","Klopt: waarvoor grond gebruikt mag worden.","Nee, het juiste antwoord is «Waarvoor grond gebruikt mag worden»."],"uh":"Waarvoor grond gebruikt mag worden."},{"v":"Wat is de bestemming van een gebied?","o":["De functie die het krijgt","De prijs","De bevolking","Het weer"],"c":0,"d":2,"u":"De functie, zoals wonen of natuur.","uo":["Klopt: de functie, zoals wonen of natuur.","Nee, het juiste antwoord is «De functie die het krijgt».","Nee, het juiste antwoord is «De functie die het krijgt».","Nee, het juiste antwoord is «De functie die het krijgt»."],"uh":"De functie, zoals wonen of natuur."},{"v":"Wat doe je bij een belangenafweging?","o":["Eén belang blind kiezen","Niets doen","Alles verbieden","Belangen tegen elkaar afwegen"],"c":3,"d":3,"u":"Verschillende belangen tegen elkaar afwegen.","uo":["Nee, het juiste antwoord is «Belangen tegen elkaar afwegen».","Nee, het juiste antwoord is «Belangen tegen elkaar afwegen».","Nee, het juiste antwoord is «Belangen tegen elkaar afwegen».","Klopt: verschillende belangen tegen elkaar afwegen."],"uh":"Belangen tegen elkaar afwegen: Verschillende belangen tegen elkaar afwegen."},{"v":"Wat is een woonfunctie?","o":["Een gebied voor fabrieken","Een gebied om te wonen","Een natuurgebied","Een haven"],"c":1,"d":1,"u":"Een gebied om te wonen.","uo":["Dat is industrie.","Klopt: een gebied om te wonen.","Nee, het juiste antwoord is «Een gebied om te wonen».","Nee, het juiste antwoord is «Een gebied om te wonen»."],"uh":"Een gebied om te wonen."},{"v":"Wat is een natuurgebied?","o":["Een industrieterrein","Een woonwijk","Beschermd gebied voor planten en dieren","Een haven"],"c":2,"d":2,"u":"Beschermde natuur.","uo":["Nee, het juiste antwoord is «Beschermd gebied voor planten en dieren».","Nee, het juiste antwoord is «Beschermd gebied voor planten en dieren».","Klopt: beschermde natuur.","Nee, het juiste antwoord is «Beschermd gebied voor planten en dieren»."],"uh":"Beschermd gebied voor planten en dieren: Beschermde natuur."},{"v":"Waarom is ruimtelijke ordening in Nederland belangrijk?","o":["Het land is klein en dichtbevolkt","Er is veel lege ruimte","Er wonen weinig mensen","Er is geen water"],"c":0,"d":3,"u":"Weinig ruimte, veel mensen.","uo":["Klopt: weinig ruimte, veel mensen.","Juist niet, het juiste antwoord is «Het land is klein en dichtbevolkt».","Er wonen juist veel mensen.","Er is juist veel water."],"uh":"Het land is klein en dichtbevolkt: Weinig ruimte, veel mensen."},{"v":"Wat is een recreatiefunctie?","o":["Wonen","Werken in een fabriek","Een haven","Een gebied voor ontspanning"],"c":3,"d":2,"u":"Een gebied voor ontspanning.","uo":["Dat is wonen.","Dat is industrie.","Nee, het juiste antwoord is «Een gebied voor ontspanning».","Klopt: een gebied voor ontspanning."],"uh":"Een gebied voor ontspanning."},{"v":"Wat is een industriegebied?","o":["Een natuurgebied","Een gebied voor bedrijven en fabrieken","Een woonwijk","Een park"],"c":1,"d":1,"u":"Een gebied voor bedrijven.","uo":["Juist niet, het juiste antwoord is «Een gebied voor bedrijven en fabrieken».","Klopt: een gebied voor bedrijven.","Nee, het juiste antwoord is «Een gebied voor bedrijven en fabrieken».","Nee, het juiste antwoord is «Een gebied voor bedrijven en fabrieken»."],"uh":"Een gebied voor bedrijven."},{"v":"Wat is een belang?","o":["Een gebouw","Een wet","Het voordeel dat iemand ergens bij heeft","Een straf"],"c":2,"d":2,"u":"Wat iemand ergens bij te winnen heeft.","uo":["Nee, het juiste antwoord is «Het voordeel dat iemand ergens bij heeft».","Nee, het juiste antwoord is «Het voordeel dat iemand ergens bij heeft».","Klopt: wat iemand ergens bij te winnen heeft.","Nee, het juiste antwoord is «Het voordeel dat iemand ergens bij heeft»."],"uh":"Het voordeel dat iemand ergens bij heeft: Wat iemand ergens bij te winnen heeft."},{"v":"Wie bepaalt mede de ruimtelijke ordening?","o":["De overheid","Een winkel","Een school","Een sportclub"],"c":0,"d":2,"u":"De overheid bepaalt mede het ruimtegebruik.","uo":["Klopt: de overheid bepaalt mede het ruimtegebruik.","Nee, het juiste antwoord is «De overheid».","Nee, het juiste antwoord is «De overheid».","Nee, het juiste antwoord is «De overheid»."],"uh":"De overheid bepaalt mede het ruimtegebruik."}],"begrippen":[{"t":"Ruimtelijke ordening","d":"het indelen en plannen van het gebruik van de ruimte"},{"t":"Bestemmingsplan","d":"een plan dat vastlegt waarvoor grond gebruikt mag worden"},{"t":"Bestemming","d":"de functie die een gebied volgens het plan krijgt"},{"t":"Functie","d":"het gebruik of doel van een gebied"},{"t":"Belang","d":"het voordeel dat iemand bij iets heeft"},{"t":"Belangenafweging","d":"het tegen elkaar afwegen van verschillende belangen"},{"t":"Woonfunctie","d":"het gebruik van een gebied om te wonen"},{"t":"Recreatiefunctie","d":"het gebruik van een gebied voor ontspanning"},{"t":"Industriegebied","d":"een gebied bestemd voor bedrijven en fabrieken"},{"t":"Natuurgebied","d":"een gebied dat beschermd is voor planten en dieren"},{"t":"Verstedelijking","d":"de groei van steden en het stedelijk ruimtegebruik"},{"t":"Infrastructuur","d":"voorzieningen zoals wegen en verbindingen in een gebied"}],"sam":"<div class=\"sam-intro\"><strong>Ruimtelijke ordening</strong> is het plannen van het gebruik van de ruimte. In een <strong>bestemmingsplan</strong> legt de overheid vast welke <strong>bestemming</strong> een gebied krijgt: wonen, werken of natuur.</div><div class=\"sam-head\">1. De ruimte plannen</div><p>Nederland is klein en dichtbevolkt, dus de ruimte wordt zorgvuldig verdeeld: dat is <strong>ruimtelijke ordening</strong>. In een <strong>bestemmingsplan</strong> legt de gemeente vast waarvoor grond gebruikt mag worden. De <strong>bestemming</strong> is de functie die een gebied krijgt; de <strong>functie</strong> is het gebruik ervan, zoals wonen of natuur.</p><div class=\"sam-head\">2. Belangen afwegen</div><p>Bij het inrichten van een gebied botsen vaak verschillende <strong>belangen</strong>. De overheid maakt dan een <strong>belangenafweging</strong>. Zo kies je tussen een <strong>woonfunctie</strong> en een <strong>recreatiefunctie</strong>, of tussen een <strong>industriegebied</strong> en een beschermd <strong>natuurgebied</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ruimtelijke ordening</div><div class=\"sam-definitie-body\">het indelen en plannen van het gebruik van de ruimte.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bestemmingsplan</div><div class=\"sam-definitie-body\">een plan dat vastlegt waarvoor grond gebruikt mag worden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bestemming</div><div class=\"sam-definitie-body\">de functie die een gebied volgens het plan krijgt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Functie</div><div class=\"sam-definitie-body\">het gebruik of doel van een gebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Belang</div><div class=\"sam-definitie-body\">het voordeel dat iemand bij iets heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Belangenafweging</div><div class=\"sam-definitie-body\">het tegen elkaar afwegen van verschillende belangen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Woonfunctie</div><div class=\"sam-definitie-body\">het gebruik van een gebied om te wonen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recreatiefunctie</div><div class=\"sam-definitie-body\">het gebruik van een gebied voor ontspanning.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Industriegebied</div><div class=\"sam-definitie-body\">een gebied bestemd voor bedrijven en fabrieken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Natuurgebied</div><div class=\"sam-definitie-body\">een gebied dat beschermd is voor planten en dieren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verstedelijking</div><div class=\"sam-definitie-body\">de groei van steden en het stedelijk ruimtegebruik.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Infrastructuur</div><div class=\"sam-definitie-body\">voorzieningen zoals wegen en verbindingen in een gebied.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Ruimtelijke ordening»</b> is de ruimte plannen, terwijl <b>«Bestemmingsplan»</b> plan voor grondgebruik is. <b>«Bestemmingsplan»</b> is plan voor grondgebruik, terwijl <b>«Bestemming»</b> toegewezen functie is. <b>«Bestemming»</b> is toegewezen functie, terwijl <b>«Functie»</b> gebruik van een gebied is. <b>«Belang»</b> is wat iemand wil, terwijl <b>«Belangenafweging»</b> belangen afwegen is.</div>"},"F":{"sv":[{"v":"Wat is een grens?","o":["Altijd een rivier","De lijn die twee gebieden scheidt","Een stad","Altijd een berg"],"c":1,"d":1,"u":"De scheidingslijn tussen gebieden.","uo":["Niet altijd.","Klopt: de scheidingslijn tussen gebieden.","Nee, het juiste antwoord is «De lijn die twee gebieden scheidt».","Niet altijd."],"uh":"De lijn die twee gebieden scheidt: De scheidingslijn tussen gebieden."},{"v":"Wat is een natuurlijke grens?","o":["Een rechte lijn op de kaart","Een muur","Een grens langs een rivier of gebergte","Een stad"],"c":2,"d":2,"u":"Valt samen met een rivier of gebergte.","uo":["Nee, het juiste antwoord is «Een grens langs een rivier of gebergte».","Nee, het juiste antwoord is «Een grens langs een rivier of gebergte».","Klopt: valt samen met een rivier of gebergte.","Nee, het juiste antwoord is «Een grens langs een rivier of gebergte»."],"uh":"Een grens langs een rivier of gebergte: Valt samen met een rivier of gebergte."},{"v":"Wat is een migratiestroom?","o":["Een grote verplaatsing van mensen","Een rivier","Een grens","Een cultuur"],"c":0,"d":2,"u":"Een grote verhuizing van mensen tussen gebieden.","uo":["Klopt: een grote verhuizing van mensen tussen gebieden.","Nee, het juiste antwoord is «Een grote verplaatsing van mensen».","Nee, het juiste antwoord is «Een grote verplaatsing van mensen».","Nee, het juiste antwoord is «Een grote verplaatsing van mensen»."],"uh":"Een grote verhuizing van mensen tussen gebieden."},{"v":"Wat is identiteit?","o":["Een grens","Een rivier","Een wet","Het gevoel bij een groep te horen"],"c":3,"d":2,"u":"Het gevoel ergens bij te horen.","uo":["Nee, het juiste antwoord is «Het gevoel bij een groep te horen».","Nee, het juiste antwoord is «Het gevoel bij een groep te horen».","Nee, het juiste antwoord is «Het gevoel bij een groep te horen».","Klopt: het gevoel ergens bij te horen."],"uh":"Het gevoel ergens bij te horen."},{"v":"Wat is een cultuurgebied?","o":["Een leeg gebied","Een gebied met een gedeelde cultuur en taal","Een woestijn","Een zee"],"c":1,"d":2,"u":"Een gebied met een gedeelde cultuur.","uo":["Nee, het juiste antwoord is «Een gebied met een gedeelde cultuur en taal».","Klopt: een gebied met een gedeelde cultuur.","Nee, het juiste antwoord is «Een gebied met een gedeelde cultuur en taal».","Nee, het juiste antwoord is «Een gebied met een gedeelde cultuur en taal»."],"uh":"Een gebied met een gedeelde cultuur."},{"v":"Wat is integratie?","o":["Gescheiden leven","Vertrekken","Meedoen in de samenleving","Een grens"],"c":2,"d":2,"u":"Nieuwkomers doen mee in de samenleving.","uo":["Dat is het tegenovergestelde.","Nee, het juiste antwoord is «Meedoen in de samenleving».","Klopt: nieuwkomers doen mee in de samenleving.","Nee, het juiste antwoord is «Meedoen in de samenleving»."],"uh":"Meedoen in de samenleving: Nieuwkomers doen mee in de samenleving."},{"v":"Wat is een vluchteling?","o":["Iemand die zijn land ontvlucht","Een toerist","Een handelaar","Een ambtenaar"],"c":0,"d":1,"u":"Ontvlucht gevaar.","uo":["Klopt: ontvlucht gevaar.","Nee, het juiste antwoord is «Iemand die zijn land ontvlucht».","Nee, het juiste antwoord is «Iemand die zijn land ontvlucht».","Nee, het juiste antwoord is «Iemand die zijn land ontvlucht»."],"uh":"Iemand die zijn land ontvlucht: Ontvlucht gevaar."},{"v":"Wat is een territoriaal conflict?","o":["Een sportwedstrijd","Een verkiezing","Een handelsdeal","Een conflict over gebied"],"c":3,"d":3,"u":"Een conflict over het bezit van een gebied.","uo":["Nee, het juiste antwoord is «Een conflict over gebied».","Nee, het juiste antwoord is «Een conflict over gebied».","Nee, het juiste antwoord is «Een conflict over gebied».","Klopt: een conflict over het bezit van een gebied."],"uh":"Een conflict over het bezit van een gebied."},{"v":"Wat hoort bij cultuur?","o":["Alleen het weer","Gewoonten, taal en gebruiken","Alleen de economie","Alleen grenzen"],"c":1,"d":2,"u":"Gewoonten, taal en gebruiken van een groep.","uo":["Nee, het juiste antwoord is «Gewoonten, taal en gebruiken».","Klopt: gewoonten, taal en gebruiken van een groep.","Nee, het juiste antwoord is «Gewoonten, taal en gebruiken».","Nee, het juiste antwoord is «Gewoonten, taal en gebruiken»."],"uh":"Gewoonten, taal en gebruiken van een groep."},{"v":"Wat is nationaliteit?","o":["Een cultuur","Een grens","Het behoren tot een bepaald land","Een rivier"],"c":2,"d":2,"u":"Bij een bepaald land horen.","uo":["Nee, het juiste antwoord is «Het behoren tot een bepaald land».","Nee, het juiste antwoord is «Het behoren tot een bepaald land».","Klopt: bij een bepaald land horen.","Nee, het juiste antwoord is «Het behoren tot een bepaald land»."],"uh":"Het behoren tot een bepaald land: Bij een bepaald land horen."},{"v":"Wat is een territorium?","o":["Het gebied waarover een land zeggenschap heeft","Een cultuur","Een migratiestroom","Een rivier"],"c":0,"d":2,"u":"Het grondgebied van een land.","uo":["Klopt: het grondgebied van een land.","Nee, het juiste antwoord is «Het gebied waarover een land zeggenschap heeft».","Nee, het juiste antwoord is «Het gebied waarover een land zeggenschap heeft».","Nee, het juiste antwoord is «Het gebied waarover een land zeggenschap heeft»."],"uh":"Het gebied waarover een land zeggenschap heeft: Het grondgebied van een land."}],"begrippen":[{"t":"Grens","d":"de lijn die twee gebieden of landen van elkaar scheidt"},{"t":"Natuurlijke grens","d":"een grens die samenvalt met een rivier of gebergte"},{"t":"Migratiestroom","d":"een grote verplaatsing van mensen tussen gebieden"},{"t":"Cultuurgebied","d":"een gebied met een gedeelde cultuur en taal"},{"t":"Identiteit","d":"het gevoel bij een groep of gebied te horen"},{"t":"Nationaliteit","d":"het behoren tot een bepaald land"},{"t":"Territorium","d":"het gebied waarover een land zeggenschap heeft"},{"t":"Territoriaal conflict","d":"een conflict over het bezit van een gebied"},{"t":"Integratie","d":"het opgaan van migranten in de samenleving"},{"t":"Vluchteling","d":"iemand die zijn land ontvlucht vanwege gevaar"},{"t":"Cultuur","d":"de gewoonten, taal en gebruiken van een groep"},{"t":"Godsdienst","d":"een gedeeld geloof binnen een cultuur"}],"sam":"<div class=\"sam-intro\">Een <strong>grens</strong> scheidt gebieden; soms valt hij samen met een rivier of gebergte. <strong>Migratiestromen</strong> verplaatsen mensen tussen <strong>cultuurgebieden</strong>, en gedeelde taal en gewoonten vormen een <strong>identiteit</strong>.</div><div class=\"sam-head\">1. Grenzen en gebied</div><p>Een <strong>grens</strong> is de lijn die twee gebieden scheidt. Een <strong>natuurlijke grens</strong> valt samen met bijvoorbeeld een rivier of gebergte. Het gebied waarover een land zeggenschap heeft, is het <strong>territorium</strong>; over het bezit ervan ontstaat soms een <strong>territoriaal conflict</strong>.</p><div class=\"sam-head\">2. Migratie, cultuur en identiteit</div><p>Door <strong>migratiestromen</strong> verhuizen grote groepen mensen, soms als <strong>vluchteling</strong>. Een <strong>cultuurgebied</strong> deelt taal en gewoonten (de <strong>cultuur</strong>) en soms een <strong>godsdienst</strong>. Dat gedeelde gevoel erbij te horen is de <strong>identiteit</strong>. <strong>Integratie</strong> is het meedoen van nieuwkomers in de samenleving.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grens</div><div class=\"sam-definitie-body\">de lijn die twee gebieden of landen van elkaar scheidt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Natuurlijke grens</div><div class=\"sam-definitie-body\">een grens die samenvalt met een rivier of gebergte.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Migratiestroom</div><div class=\"sam-definitie-body\">een grote verplaatsing van mensen tussen gebieden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cultuurgebied</div><div class=\"sam-definitie-body\">een gebied met een gedeelde cultuur en taal.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Identiteit</div><div class=\"sam-definitie-body\">het gevoel bij een groep of gebied te horen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nationaliteit</div><div class=\"sam-definitie-body\">het behoren tot een bepaald land.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Territorium</div><div class=\"sam-definitie-body\">het gebied waarover een land zeggenschap heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Territoriaal conflict</div><div class=\"sam-definitie-body\">een conflict over het bezit van een gebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Integratie</div><div class=\"sam-definitie-body\">het opgaan van migranten in de samenleving.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vluchteling</div><div class=\"sam-definitie-body\">iemand die zijn land ontvlucht vanwege gevaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cultuur</div><div class=\"sam-definitie-body\">de gewoonten, taal en gebruiken van een groep.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Godsdienst</div><div class=\"sam-definitie-body\">een gedeeld geloof binnen een cultuur.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Grens»</b> is scheidingslijn, terwijl <b>«Natuurlijke grens»</b> grens langs de natuur is. <b>«Migratiestroom»</b> is grote verhuisstroom, terwijl <b>«Vluchteling»</b> ontvlucht gevaar is. <b>«Cultuurgebied»</b> is gebied met gedeelde cultuur, terwijl <b>«Cultuur»</b> gewoonten en gebruiken is. <b>«Identiteit»</b> is gevoel van erbij horen, terwijl <b>«Cultuur»</b> gewoonten en gebruiken is.</div>"}});